import{state}from"./state.js";import{changePassword}from"./api.js";import{showToast,closeModal,openModal}from"./utils.js";export function openChangePasswordModal(){document.getElementById("old-password").value="",document.getElementById("new-password").value="",openModal("change-password-modal")}export async function saveNewPassword(){const e=document.getElementById("old-password").value,s=document.getElementById("new-password").value;if(!s||s.length<6)return showToast("Новый пароль должен быть не менее 6 символов","error");const o=await changePassword(e,s);o.success?(showToast("Пароль успешно изменен","success"),closeModal("change-password-modal")):showToast(o.error||"Ошибка при смене пароля","error")}export async function saveNewPasswordInline(){const e=document.getElementById("settings-old-password-inline").value,s=document.getElementById("settings-new-password-inline").value;if(!s||s.length<6)return showToast("Новый пароль должен быть не менее 6 символов","error");const o=await changePassword(e,s);o.success?(showToast("Пароль успешно изменен","success"),document.getElementById("settings-old-password-inline").value="",document.getElementById("settings-new-password-inline").value=""):showToast(o.error||"Ошибка при смене пароля","error")}